WITH filtered AS (SELECT id, store_id, product_id, sale_date, revenue + units AS revenue_per_unit FROM store_sales WHERE store_id = 5) SELECT *, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY revenue_per_unit ASC, id ASC) AS row_seq, LEAD(revenue_per_unit, 1) OVER (ORDER BY revenue_per_unit ASC, id ASC) AS next_revenue_per_unit, RANK() OVER (PARTITION BY store_id, product_id ORDER BY revenue_per_unit DESC NULLS LAST) AS revenue_per_unit_rank FROM filtered;
